//! Native REST transport for the optional remote backend.
//!
//! This mirrors the wire contract generated by Dioxus server functions:
//! query parameters are serialized through `ClientRequest`, bodies are JSON
//! objects keyed by argument name, successful responses are plain JSON, and
//! errors use the `{ message, code, data }` envelope.
use crate::domain::health::Health;
#[cfg(not(target_arch = "wasm32"))]
use crate::domain::health::{API_VERSION, API_VERSION_HEADER};
#[cfg(not(target_arch = "wasm32"))]
use dioxus::fullstack::{ClientRequest, Method};
use dioxus_fullstack_core::ServerFnError;
#[cfg(target_arch = "wasm32")]
use reqwest::Method;
use serde::de::DeserializeOwned;
use serde_json::Value;
use std::time::Duration;

const CALL_TIMEOUT: Duration = Duration::from_secs(15);
const HEALTH_TIMEOUT: Duration = Duration::from_secs(5);

/// Backup export/import can move large files and run migrations on the
/// server, so it needs a much larger budget than ordinary API calls.
#[cfg(not(target_arch = "wasm32"))]
pub const DATA_TRANSFER_TIMEOUT: Duration = Duration::from_secs(10 * 60);

/// Call a remote API endpoint using the configured backend URL.
pub async fn call<T>(
    method: Method,
    path: &str,
    query: Option<Value>,
    body: Option<Value>,
) -> Result<T, ServerFnError>
where
    T: DeserializeOwned,
{
    call_with_timeout(method, path, query, body, CALL_TIMEOUT).await
}

/// Call a remote API endpoint with an explicit timeout.
pub async fn call_with_timeout<T>(
    method: Method,
    path: &str,
    query: Option<Value>,
    body: Option<Value>,
    timeout: Duration,
) -> Result<T, ServerFnError>
where
    T: DeserializeOwned,
{
    if let Some(alert) = crate::backend::remote_blocked() {
        return Err(ServerFnError::new(alert.message()));
    }
    let base_url = crate::backend::remote_base_url()
        .ok_or_else(|| ServerFnError::new("No remote backend URL is configured."))?;
    call_at(&base_url, method, path, query, body, timeout).await
}

/// Health check against an explicit base URL. Used by Settings and startup.
pub async fn health_at(base_url: &str) -> Result<Health, ServerFnError> {
    call_at(
        base_url,
        Method::GET,
        "/api/health",
        None,
        None,
        HEALTH_TIMEOUT,
    )
    .await
}

/// Health check against the configured remote backend.
pub async fn health_at_current() -> Result<Health, ServerFnError> {
    let base_url = crate::backend::remote_base_url()
        .ok_or_else(|| ServerFnError::new("No remote backend URL is configured."))?;
    health_at(&base_url).await
}

#[cfg(not(target_arch = "wasm32"))]
async fn call_at<T>(
    base_url: &str,
    method: Method,
    path: &str,
    query: Option<Value>,
    body: Option<Value>,
    timeout: Duration,
) -> Result<T, ServerFnError>
where
    T: DeserializeOwned,
{
    if let Some(error) = crate::backend::remote_transport_error(base_url) {
        return Err(ServerFnError::new(error));
    }
    let empty = serde_json::json!({});
    let query_value = query.as_ref().unwrap_or(&empty);

    // Let ClientRequest perform the serde_qs query serialization and carry the
    // global request headers (including the API version header). Then replace
    // the origin with the configured backend URL.
    let mut request = ClientRequest::new(method.clone(), path.to_string(), query_value);
    let base_url = base_url.trim_end_matches('/');
    let target = match request.url.query() {
        Some(query) => format!("{base_url}{}?{query}", request.url.path()),
        None => format!("{base_url}{}", request.url.path()),
    };
    request.url = target
        .parse()
        .map_err(|error| ServerFnError::new(format!("Invalid backend URL: {error}")))?;

    let client = native_client()?;
    let mut builder = client
        .request(method, request.url.clone())
        .header(API_VERSION_HEADER, API_VERSION.to_string())
        .timeout(timeout);
    if let Some(token) = crate::backend::session_token() {
        builder = builder.header("authorization", format!("Bearer {token}"));
    }
    if let Some(body) = body {
        let is_empty_object = body
            .as_object()
            .map(|object| object.is_empty())
            .unwrap_or(false);
        if !body.is_null() && !is_empty_object {
            builder = builder.json(&body);
        }
    }

    let response = builder.send().await.map_err(|error| {
        ServerFnError::Request(dioxus::fullstack::reqwest_error_to_request_error(error))
    })?;
    let status = response.status();
    let bytes = response.bytes().await.map_err(|error| {
        ServerFnError::Request(dioxus::fullstack::reqwest_error_to_request_error(error))
    })?;
    if status == reqwest::StatusCode::UNAUTHORIZED {
        crate::backend::clear_session_token();
    }

    if status.is_success() {
        return serde_json::from_slice::<T>(&bytes).map_err(|error| {
            ServerFnError::new(format!(
                "The remote server returned an invalid response for {path}: {error}"
            ))
        });
    }

    #[derive(serde::Deserialize)]
    struct RemoteErrorPayload {
        message: String,
        code: u16,
        #[serde(default)]
        data: Option<Value>,
    }

    match serde_json::from_slice::<RemoteErrorPayload>(&bytes) {
        Ok(error) => Err(ServerFnError::ServerError {
            message: error.message,
            code: error.code,
            details: error.data,
        }),
        Err(_) => Err(ServerFnError::ServerError {
            message: format!("The remote server returned HTTP {status} for {path}."),
            code: status.as_u16(),
            details: None,
        }),
    }
}

#[cfg(not(target_arch = "wasm32"))]
fn native_client() -> Result<reqwest::Client, ServerFnError> {
    use std::sync::OnceLock;
    static CLIENT: OnceLock<Result<reqwest::Client, String>> = OnceLock::new();
    CLIENT
        .get_or_init(|| {
            let mut builder = reqwest::Client::builder()
                .redirect(reqwest::redirect::Policy::none())
                .user_agent("address-explorer");
            if let Ok(path) = std::env::var("ADDRESS_EXPLORER_TLS_CA") {
                let pem = std::fs::read(&path)
                    .map_err(|error| format!("could not read {path}: {error}"))?;
                let certificate = reqwest::Certificate::from_pem(&pem)
                    .map_err(|error| format!("could not parse {path}: {error}"))?;
                builder = builder.add_root_certificate(certificate);
            }
            builder
                .build()
                .map_err(|error| format!("could not build the remote HTTP client: {error}"))
        })
        .clone()
        .map_err(ServerFnError::new)
}

/// Browser remote transport. Unlike the native helper, this builds an
/// absolute URL because the Dioxus web client always uses same-origin paths.
#[cfg(target_arch = "wasm32")]
async fn call_at<T>(
    base_url: &str,
    method: Method,
    path: &str,
    query: Option<Value>,
    body: Option<Value>,
    _timeout: Duration,
) -> Result<T, ServerFnError>
where
    T: DeserializeOwned,
{
    use crate::domain::health::{API_VERSION, API_VERSION_HEADER};

    if let Some(error) = crate::backend::remote_transport_error(base_url) {
        return Err(ServerFnError::new(error));
    }
    let mut url = format!("{}{}", base_url.trim_end_matches('/'), path);
    if let Some(query) = query.as_ref().and_then(Value::as_object) {
        let pairs = query
            .iter()
            .filter_map(|(key, value)| {
                let value = match value {
                    Value::String(value) => value.clone(),
                    Value::Number(value) => value.to_string(),
                    Value::Bool(value) => value.to_string(),
                    Value::Null => return None,
                    _ => value.to_string(),
                };
                Some((key.clone(), value))
            })
            .collect::<Vec<_>>();
        if !pairs.is_empty() {
            let query = serde_urlencoded::to_string(pairs)
                .map_err(|error| ServerFnError::new(format!("Invalid query: {error}")))?;
            url.push('?');
            url.push_str(&query);
        }
    }

    let client = reqwest::Client::new();
    let mut request = client
        .request(method, &url)
        .header(API_VERSION_HEADER, API_VERSION.to_string());
    if let Some(token) = crate::backend::session_token() {
        request = request.header("authorization", format!("Bearer {token}"));
    }
    let request = match body {
        Some(body)
            if !body.is_null()
                && !body
                    .as_object()
                    .map(|object| object.is_empty())
                    .unwrap_or(false) =>
        {
            request.json(&body)
        }
        _ => request,
    };

    let response = request.send().await.map_err(|error| {
        ServerFnError::new(format!(
            "Could not reach the remote backend at {base_url}: {error}. Check the URL, CORS, and network connection."
        ))
    })?;
    let status = response.status();
    let bytes = response.bytes().await.map_err(|error| {
        ServerFnError::new(format!("Could not read the remote response: {error}"))
    })?;
    if status == reqwest::StatusCode::UNAUTHORIZED {
        crate::backend::clear_session_token();
    }

    if status.is_success() {
        return serde_json::from_slice::<T>(&bytes).map_err(|error| {
            ServerFnError::new(format!(
                "The remote server returned an invalid response for {path}: {error}"
            ))
        });
    }

    #[derive(serde::Deserialize)]
    struct RemoteErrorPayload {
        message: String,
        code: u16,
        #[serde(default)]
        data: Option<Value>,
    }

    match serde_json::from_slice::<RemoteErrorPayload>(&bytes) {
        Ok(error) => Err(ServerFnError::ServerError {
            message: error.message,
            code: error.code,
            details: error.data,
        }),
        Err(_) => Err(ServerFnError::ServerError {
            message: format!("The remote server returned HTTP {status} for {path}."),
            code: status.as_u16(),
            details: None,
        }),
    }
}

#[cfg(test)]
mod tests {
    use super::*;
    use crate::domain::health::API_VERSION;
    use dioxus::server::axum::{
        extract::Query,
        http::StatusCode,
        routing::{get, post},
        Json, Router,
    };
    use serde_json::json;
    use std::collections::HashMap;

    async fn mock_server() -> String {
        let app = Router::new()
            .route(
                "/api/health",
                get(|| async {
                    Json(Health {
                        app_version: "test".to_string(),
                        api_version: API_VERSION,
                        tls_fingerprint: None,
                    })
                }),
            )
            .route(
                "/api/echo",
                post(|Json(body): Json<Value>| async move { Json(body) }),
            )
            .route(
                "/api/query",
                get(|Query(query): Query<HashMap<String, String>>| async move { Json(query) }),
            )
            .route(
                "/api/error",
                get(|| async {
                    (
                        StatusCode::UPGRADE_REQUIRED,
                        Json(json!({
                            "message": "API version mismatch: client 1, server 2",
                            "code": 426,
                            "data": { "server_api_version": 2 }
                        })),
                    )
                }),
            );

        let listener = tokio::net::TcpListener::bind("127.0.0.1:0")
            .await
            .expect("bind mock server");
        let address = listener.local_addr().expect("mock server address");
        tokio::spawn(async move {
            let _ = dioxus::server::axum::serve(listener, app).await;
        });
        format!("http://{address}")
    }

    #[tokio::test]
    async fn health_reports_the_server_api_version() {
        let base = mock_server().await;
        let health = health_at(&base).await.expect("health response");
        assert_eq!(health.api_version, API_VERSION);
    }

    #[tokio::test]
    async fn json_body_round_trips() {
        let base = mock_server().await;
        let body = json!({ "hello": "world" });
        let echoed: Value = call_at(
            &base,
            Method::POST,
            "/api/echo",
            None,
            Some(body.clone()),
            CALL_TIMEOUT,
        )
        .await
        .expect("echo response");
        assert_eq!(echoed, body);
    }

    #[tokio::test]
    async fn query_parameters_round_trip() {
        let base = mock_server().await;
        let result: HashMap<String, String> = call_at(
            &base,
            Method::GET,
            "/api/query",
            Some(json!({ "symbol": "USD", "close_time": 42 })),
            None,
            CALL_TIMEOUT,
        )
        .await
        .expect("query response");
        assert_eq!(result.get("symbol").map(String::as_str), Some("USD"));
        assert_eq!(result.get("close_time").map(String::as_str), Some("42"));
    }

    #[tokio::test]
    async fn version_error_envelope_is_preserved() {
        let base = mock_server().await;
        let error = call_at::<Value>(&base, Method::GET, "/api/error", None, None, CALL_TIMEOUT)
            .await
            .expect_err("version error");
        match error {
            ServerFnError::ServerError {
                message,
                code,
                details,
            } => {
                assert_eq!(code, 426);
                assert!(message.contains("API version mismatch"));
                assert_eq!(
                    details
                        .as_ref()
                        .and_then(|details| details.get("server_api_version"))
                        .and_then(Value::as_u64),
                    Some(2)
                );
            }
            other => panic!("expected a server error, got {other}"),
        }
    }
}
